INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Net Investment Income Tax (3.8%) comparative analysis
(3, 'Individual Taxation: Income', 'Reeves, a single taxpayer, has $180,000 in wages and $50,000 in net investment income in 2026. Her colleague, Wallace, also single, has $220,000 in wages and $15,000 in net investment income. Neither has above-the-line deductions. How does the 3.8% Net Investment Income Tax under Section 1411 apply to each taxpayer?', '["Reeves owes NIIT of $1,140; Wallace owes NIIT of $570", "Reeves owes NIIT of $1,900; Wallace owes NIIT of $570", "Both owe NIIT on 100% of their net investment income", "Neither owes NIIT because their wages alone do not exceed $200,000"]'::jsonb, 0, 'Under Section 1411, the 3.8% NIIT applies to the lesser of net investment income or MAGI exceeding the $200,000 single threshold. Reeves: MAGI $230,000 minus $200,000 = $30,000; lesser of $30,000 and $50,000 NII = $30,000 x 3.8% = $1,140. Wallace: MAGI $235,000 minus $200,000 = $35,000; lesser of $35,000 and $15,000 NII = $15,000 x 3.8% = $570. Choice B incorrectly applies the tax to Reeves''s full NII rather than the lesser-of calculation.', 'hard', 4),

-- Q2: medium / L2 — Qualified scholarship exclusion (tuition vs room and board)
(3, 'Individual Taxation: Income', 'Navarro receives a $30,000 scholarship for graduate studies in 2026. Of this amount, $22,000 is designated for tuition and required fees, and $8,000 is designated for room and board. Under Section 117, how much of the scholarship is included in Navarro''s gross income?', '["$0", "$8,000", "$22,000", "$30,000"]'::jsonb, 1, 'Under Section 117, qualified scholarships used for tuition and required fees at eligible institutions are excluded from gross income. Amounts designated for room and board are not qualified expenses and must be included. Navarro excludes $22,000 for tuition but includes the $8,000 for room and board. Choice A incorrectly excludes the entire scholarship, ignoring that Section 117 limits the exclusion to tuition and required fees only.', 'medium', 2),

-- Q3: medium / L2 — Section 121 home sale exclusion
(3, 'Individual Taxation: Income', 'Ortega, a single taxpayer, sells her primary residence in 2026 for $520,000. She purchased it seven years ago for $240,000 and has lived there continuously. Her realized gain is $280,000. Under Section 121, how much gain must Ortega recognize on the sale?', '["$0", "$280,000", "$30,000", "$250,000"]'::jsonb, 2, 'Section 121 allows single taxpayers to exclude up to $250,000 of gain on the sale of a principal residence if they owned and used the home for at least two of the five years preceding the sale. Ortega''s $280,000 gain exceeds the $250,000 exclusion, so she recognizes $30,000. Choice A incorrectly assumes the entire gain is excluded, but the exclusion is capped at $250,000 for single filers ($500,000 for MFJ).', 'medium', 2),

-- Q4: medium / L2 — HSA contribution as above-the-line deduction
(3, 'Individual Taxation: Income', 'Nakamura, covered by a qualifying high-deductible health plan, contributes $4,150 to a Health Savings Account in 2026. He has $62,000 in wages and no other income. What is Nakamura''s adjusted gross income?', '["$57,850", "$58,000", "$62,000", "$66,150"]'::jsonb, 0, 'Under Section 223, HSA contributions are above-the-line deductions subtracted from gross income to arrive at AGI, available regardless of whether the taxpayer itemizes. Nakamura''s AGI = $62,000 minus $4,150 = $57,850. Choice C incorrectly treats the HSA contribution as a below-the-line deduction that would not reduce AGI. Above-the-line treatment lowers AGI, potentially increasing eligibility for phase-out-dependent tax benefits.', 'medium', 2),

-- Q5: medium / L3 — Medical expense deduction with 7.5% AGI floor
(3, 'Individual Taxation: Income', 'Fitzpatrick, a single taxpayer, has AGI of $80,000 in 2026. He incurred $10,000 in unreimbursed medical expenses, including $4,500 for surgery, $3,000 for prescriptions, and $2,500 for insurance premiums. If Fitzpatrick itemizes, what is his deductible medical expense amount?', '["$4,000", "$0", "$6,000", "$10,000"]'::jsonb, 0, 'Under Section 213, unreimbursed medical expenses are deductible only to the extent they exceed 7.5% of AGI. Fitzpatrick''s floor = $80,000 x 7.5% = $6,000. Total qualified expenses of $10,000 minus the $6,000 floor = $4,000 deductible. Choice C is the floor amount itself, not the deductible portion. Choice D ignores the AGI floor entirely. The 7.5% threshold ensures only significant medical costs relative to income produce a deduction.', 'medium', 3),

-- Q6: hard / L3 — Charitable contribution limits (capital gain property to public charity)
(3, 'Individual Taxation: Income', 'Blackwell has AGI of $150,000 in 2026. She donates stock held for three years with a fair market value of $55,000 and a basis of $18,000 to the American Red Cross, a 50% limit public charity. What is Blackwell''s maximum charitable deduction for the stock donation in 2026?', '["$18,000", "$55,000", "$90,000", "$45,000"]'::jsonb, 3, 'Under Section 170(b)(1)(C), contributions of long-term capital gain property to public charities are limited to 30% of AGI. Blackwell''s 30% limit = $150,000 x 30% = $45,000. Although the stock''s FMV is $55,000, only $45,000 is deductible in 2026; the remaining $10,000 carries forward five years. Choice A incorrectly uses basis instead of FMV. Taxpayers may elect under Section 170(b)(1)(C)(iii) to use basis and apply the higher 50% limit, but that yields only $18,000.', 'hard', 3),

-- Q7: easy / L2 — Workers' compensation exclusion
(3, 'Individual Taxation: Income', 'Bryant, a warehouse employee, receives $12,000 in workers'' compensation benefits after a job-related injury in 2026. He also receives $8,000 in short-term disability from an employer-paid policy. How much must Bryant include in gross income?', '["$0", "$12,000", "$8,000", "$20,000"]'::jsonb, 2, 'Under Section 104(a)(1), workers'' compensation benefits for job-related injuries are fully excluded from gross income. However, disability benefits from an employer-paid insurance policy are taxable because the employer paid the premiums. Bryant excludes the $12,000 workers'' compensation but includes the $8,000 disability income. Choice A incorrectly assumes both are excluded. The key distinction is that workers'' compensation is a statutory exclusion, while employer-funded disability is treated as a wage substitute.', 'easy', 2),

-- Q8: medium / L3 — SALT cap ($10,000 limit)
(3, 'Individual Taxation: Income', 'Nguyen, who files as married filing jointly, pays $7,200 in state income taxes, $4,800 in real property taxes, and $1,500 in personal property taxes in 2026. What is the maximum amount Nguyen may deduct for state and local taxes on Schedule A?', '["$7,200", "$12,000", "$13,500", "$10,000"]'::jsonb, 3, 'Under Section 164 as modified by the TCJA, the combined deduction for state income taxes (or sales taxes), real property taxes, and personal property taxes is capped at $10,000 ($5,000 MFS). Nguyen''s total SALT of $13,500 exceeds the cap, so the deduction is limited to $10,000. Choice C reflects the full amount paid without applying the cap. The $10,000 ceiling applies regardless of filing status except for MFS, which is halved to $5,000.', 'medium', 3),

-- Q9: hard / L4 — Three-tier loss limitation order (BARP framework)
(3, 'Individual Taxation: Income', 'Crawford is a 20% limited partner in Atlas Partners. His outside basis is $30,000, his at-risk amount is $22,000, and he does not materially participate. Atlas allocates Crawford an $18,000 ordinary loss. Crawford has $50,000 in wages and no passive income. Evaluate how the three-tier loss limitation rules affect Crawford''s deductible loss.', '["$0 deductible; $18,000 suspended at the passive activity tier", "$18,000 fully deductible against wages", "$18,000 passes basis and at-risk tiers, but is fully suspended as a passive loss", "$12,000 deductible; $6,000 suspended at the at-risk tier"]'::jsonb, 2, 'Under the BARP framework, losses pass sequentially through basis (Section 704(d)), at-risk (Section 465), then passive activity (Section 469). Crawford''s $18,000 loss passes the $30,000 basis limit and the $22,000 at-risk amount. However, because Crawford does not materially participate and has no passive income, the full $18,000 is suspended under Section 469. Choice A skips the first two tiers. Choice D incorrectly limits the loss at the at-risk tier when $22,000 exceeds $18,000.', 'hard', 4),

-- Q10: easy / L1 — Standard deduction for single filers
(3, 'Individual Taxation: Income', 'What is the approximate standard deduction amount for a single taxpayer in 2026?', '["$10,000", "$15,000", "$22,500", "$30,000"]'::jsonb, 1, 'The standard deduction is a fixed dollar amount indexed annually for inflation. For 2026, the approximate standard deduction for a single filer is $15,000. Choice C ($22,500) is the Head of Household amount, and choice D ($30,000) is the Married Filing Jointly amount. The standard deduction reduces taxable income for taxpayers who do not itemize deductions on Schedule A.', 'easy', 1),

-- Q11: medium / L3 — Home mortgage interest limitation ($750K cap)
(3, 'Individual Taxation: Income', 'Caldwell purchases a primary residence in 2026 with a $900,000 mortgage at 6% interest. He pays $54,000 in mortgage interest during the year. If Caldwell itemizes deductions, what is the maximum mortgage interest deduction he may claim?', '["$45,000", "$54,000", "$60,000", "$75,000"]'::jsonb, 0, 'Under Section 163(h)(3) as amended by the TCJA, mortgage interest is deductible on acquisition indebtedness up to $750,000 for loans after December 15, 2017. Caldwell''s $900,000 mortgage exceeds this limit, so the deductible portion is prorated: $54,000 x ($750,000 / $900,000) = $45,000. Choice B assumes the full interest is deductible, ignoring the $750,000 cap. Only interest attributable to the first $750,000 of mortgage debt generates a tax deduction.', 'medium', 3),

-- Q12: medium / L2 — Bartering income (FMV of services received)
(3, 'Individual Taxation: Income', 'Hoffman, an electrician, rewires a dentist''s office in exchange for $3,500 worth of dental work. Hoffman''s cost of materials for the electrical job is $800. What amount must Hoffman include in gross income from this barter transaction?', '["$0", "$800", "$2,700", "$3,500"]'::jsonb, 3, 'Under Section 61 and Reg. 1.61-2(d), when services are exchanged, each party includes in gross income the fair market value of the services received. Hoffman must include the $3,500 FMV of the dental services. His $800 materials cost is a separate business expense deducted on Schedule C, not netted against gross income. Choice C incorrectly nets the materials cost against the barter income at the gross income line.', 'medium', 2),

-- Q13: easy / L1 — Student loan interest deduction classification
(3, 'Individual Taxation: Income', 'How is the student loan interest deduction classified under Section 221?', '["An above-the-line deduction for AGI", "An itemized deduction on Schedule A", "A tax credit on Schedule 3", "A below-the-line deduction from taxable income"]'::jsonb, 0, 'Under Section 221, the student loan interest deduction (up to $2,500 annually) is an above-the-line deduction subtracted from gross income to arrive at AGI. This means it is available regardless of whether the taxpayer itemizes. Choice B incorrectly classifies it as an itemized deduction. Above-the-line status is beneficial because it directly reduces AGI, which serves as a threshold for many other tax benefits that phase out at higher income levels.', 'easy', 1),

-- Q14: medium / L2 — Head of Household filing status requirements
(3, 'Individual Taxation: Income', 'Reeves is unmarried and pays more than half the cost of maintaining a home where her 10-year-old dependent son lives all year. Her coworker Lambert is unmarried, pays all costs for her apartment, and lives alone. Which taxpayer qualifies for Head of Household filing status?', '["Both Reeves and Lambert", "Neither qualifies", "Only Lambert", "Only Reeves"]'::jsonb, 3, 'Head of Household under Section 2(b) requires the taxpayer to be (1) unmarried at year-end, (2) pay more than half the cost of maintaining a home, and (3) have a qualifying person living in the home for more than half the year. Reeves meets all three requirements. Lambert, though unmarried and paying her own costs, has no qualifying person. Choice A incorrectly grants HOH to Lambert, who fails the qualifying-person requirement.', 'medium', 2),

-- Q15: easy / L1 — AGI formula definition
(3, 'Individual Taxation: Income', 'What is the formula for calculating adjusted gross income (AGI)?', '["Gross income minus itemized deductions", "Gross income minus the standard deduction", "Gross income minus above-the-line deductions", "Taxable income plus the standard deduction"]'::jsonb, 2, 'AGI is computed by subtracting above-the-line deductions (adjustments to income) from gross income under Section 62. These include IRA contributions, student loan interest, and HSA contributions. Choice A confuses AGI with taxable income since itemized deductions are subtracted from AGI, not from gross income. AGI is a critical threshold because many credits, deductions, and exclusions phase out based on AGI levels.', 'easy', 1),

-- Q16: easy / L1 — K-1 income character retention
(3, 'Individual Taxation: Income', 'What happens to the character of income items reported on a Schedule K-1 from a partnership?', '["All items are recharacterized as ordinary income on the partner''s return", "Capital gains are converted to passive income for all partners", "All items are treated as self-employment income", "Each item retains its original character when reported by the individual partner"]'::jsonb, 3, 'Under Section 702(b), each partner''s distributive share of income, gain, loss, deduction, and credit retains its character as it passes through to the partner''s individual return. Capital gains remain capital gains, ordinary income remains ordinary, and tax-exempt income remains tax-exempt. Choice A incorrectly assumes all K-1 items become ordinary income. Character retention is fundamental to ensuring pass-through entities do not alter the tax treatment of income items.', 'easy', 1),

-- Q17: hard / L4 — Excess Business Loss limitation (Section 461(l))
(3, 'Individual Taxation: Income', 'Duncan, a single taxpayer, materially participates in a sole proprietorship that generates a $500,000 loss in 2026. She also earns $100,000 in wages. The Section 461(l) excess business loss threshold for single filers is $322,000. Evaluate Duncan''s deductible loss and the treatment of any disallowed amount.', '["$322,000 deductible; $178,000 becomes an NOL carryforward", "$422,000 deductible; $78,000 suspended indefinitely", "$500,000 fully deductible because Duncan materially participates", "$100,000 deductible; $400,000 suspended as a passive loss"]'::jsonb, 0, 'Under Section 461(l), noncorporate taxpayers cannot deduct aggregate business losses exceeding the threshold ($322,000 single) plus aggregate business gross income. Duncan''s excess = $500,000 loss minus ($0 business income + $322,000 threshold) = $178,000. The deductible portion is $322,000; the $178,000 excess becomes an NOL carryforward under Section 172. Choice C ignores the EBL cap. Choice D misapplies passive rules since Duncan materially participates, making Section 469 inapplicable.', 'hard', 4),

-- Q18: medium / L3 — Self-employment tax deduction (50% above-the-line)
(3, 'Individual Taxation: Income', 'Patel has net self-employment income of $100,000 from his consulting business in 2026. His calculated self-employment tax is $14,130. What above-the-line deduction may Patel claim for the self-employment tax?', '["$7,065", "$14,130", "$46,175", "$100,000"]'::jsonb, 0, 'Under Section 164(f), self-employed taxpayers may deduct 50% of their self-employment tax as an above-the-line deduction, mirroring the employer''s share of FICA that employees do not pay. Patel''s deduction = $14,130 x 50% = $7,065. Choice B incorrectly deducts the full SE tax rather than half. The deduction reduces AGI, which can improve eligibility for phase-out-dependent benefits like IRA deductions and education credits.', 'medium', 3),

-- Q19: easy / L1 — Moving expense deduction (military only)
(3, 'Individual Taxation: Income', 'Under current tax law, which taxpayers may claim the moving expense deduction?', '["Only active-duty members of the Armed Forces due to a military order", "Any taxpayer who moves more than 50 miles for a new job", "Self-employed taxpayers who relocate their business", "All taxpayers who move to a different state"]'::jsonb, 0, 'Under Section 217, as modified by the TCJA, the moving expense deduction is limited exclusively to active-duty military members who move pursuant to a permanent change of station order. The broader deduction previously available to all taxpayers meeting distance and time tests was suspended by the TCJA. Choice B describes the pre-TCJA rule that no longer applies to civilian taxpayers.', 'easy', 1),

-- Q20: medium / L2 — Qualifying Surviving Spouse filing status
(3, 'Individual Taxation: Income', 'Chang''s spouse died in January 2025. Chang did not remarry and maintains a home for his dependent 8-year-old son through 2026. What is Chang''s most favorable filing status for the 2026 tax year?', '["Single", "Married Filing Jointly", "Head of Household", "Qualifying Surviving Spouse"]'::jsonb, 3, 'Under Section 2(a), a taxpayer whose spouse died within the prior two years may file as Qualifying Surviving Spouse if they maintain a home for a dependent child and do not remarry. Since Chang''s spouse died in 2025 and 2026 is within the two-year window, Chang qualifies. This status provides the same standard deduction and brackets as MFJ. Choice B (MFJ) is only available for the year of death, not subsequent years.', 'medium', 2),

-- Q21: medium / L3 — Return of capital (partnership distribution)
(3, 'Individual Taxation: Income', 'Summers invested $20,000 in a limited partnership and receives a $5,000 cash distribution in 2026. The partnership reports no income or loss for the year, and the distribution is classified as a return of capital. What is the tax consequence to Summers?', '["$5,000 of ordinary income", "$0 income recognized; basis reduced by $5,000", "$5,000 of capital gain", "$5,000 of passive income"]'::jsonb, 1, 'Under Section 731(a), a cash distribution from a partnership that does not exceed the partner''s outside basis is not taxable. Instead, the partner reduces basis by the distribution amount. Summers''s basis decreases from $20,000 to $15,000 with no income recognized. Choice A incorrectly treats the return of capital as ordinary income. A return of capital merely returns the partner''s investment and is not an income event until basis reaches zero.', 'medium', 3),

-- Q22: hard / L4 — MAGI definition variations (Roth IRA vs passive rental)
(3, 'Individual Taxation: Income', 'Kessler, a single taxpayer, has AGI of $140,000 after claiming a $5,000 student loan interest deduction and $8,000 foreign earned income exclusion. She wants to determine eligibility for a Roth IRA contribution and the $25,000 passive rental loss allowance. How do the MAGI calculations differ, and which is higher?', '["Both provisions use the same MAGI of $140,000", "Roth IRA MAGI adds back both items ($153,000); rental MAGI is AGI without passive losses ($140,000) — Roth MAGI is higher", "Rental MAGI adds back student loan interest ($145,000); Roth MAGI equals AGI ($140,000) — rental MAGI is higher", "Roth IRA MAGI adds back only the foreign earned income exclusion ($148,000); rental MAGI adds back student loan interest ($145,000) — Roth MAGI is higher"]'::jsonb, 1, 'Under Section 408A, Roth IRA MAGI adds back the student loan interest deduction and foreign earned income exclusion: $140,000 + $5,000 + $8,000 = $153,000. Under Section 469(i), the rental loss allowance MAGI is AGI computed without passive activity losses — no add-backs for student loan interest or foreign income. Kessler''s rental MAGI is $140,000. Choice A incorrectly assumes MAGI is uniform across provisions. The variation in MAGI definitions is a frequent exam trap.', 'hard', 4),

-- Q23: easy / L1 — Employer-provided health insurance exclusion
(3, 'Individual Taxation: Income', 'What is the tax treatment of health insurance premiums paid by an employer on behalf of an employee?', '["Included in the employee''s gross income as a fringe benefit", "Excluded from the employee''s gross income under Section 106", "Deductible by the employee as an itemized deduction", "Taxable to the employee but subject to a 50% exclusion"]'::jsonb, 1, 'Under Section 106, employer-provided health insurance premiums are excluded from an employee''s gross income. This is one of the most valuable fringe benefit exclusions in the Code. The employer deducts the premiums as a business expense, but the employee is not taxed on the benefit. Choice A incorrectly includes the premiums in income. Choice C confuses employer-paid premiums with the self-employed health insurance deduction under Section 162(l).', 'easy', 1),

-- Q24: medium / L3 — Additional standard deduction for age 65+
(3, 'Individual Taxation: Income', 'Wagner, age 68, is single and not blind. In 2026, his only income is $40,000 in pension distributions. He does not itemize. The base standard deduction for single filers is approximately $15,000, and the additional amount for age 65 or older is approximately $1,950. What is Wagner''s taxable income?', '["$22,050", "$25,000", "$23,050", "$40,000"]'::jsonb, 2, 'Taxpayers age 65 or older receive an additional standard deduction under Section 63(f). Wagner''s total standard deduction = $15,000 base + $1,950 additional = $16,950. Taxable income = $40,000 minus $16,950 = $23,050. Choice B incorrectly uses only the base $15,000 standard deduction without the age-based addition. The additional standard deduction is higher for single and HOH filers than for married filers.', 'medium', 3),

-- Q25: easy / L1 — Auto loan interest deduction (H.R. 1)
(3, 'Individual Taxation: Income', 'Under H.R. 1, what is the maximum annual deduction for interest on a loan used to purchase a U.S.-manufactured vehicle?', '["$2,500", "$5,000", "$10,000", "$25,000"]'::jsonb, 2, 'H.R. 1 introduced an above-the-line deduction for interest paid on loans used to purchase vehicles manufactured in the United States, effective for tax years beginning after 2025. The deduction is capped at $10,000 of interest per year. Choice A reflects the student loan interest cap, not the auto loan provision. This deduction reduces AGI directly, providing a benefit regardless of whether the taxpayer itemizes.', 'easy', 1),

-- Q26: medium / L3 — Self-employed health insurance deduction (100%)
(3, 'Individual Taxation: Income', 'Vasquez, a self-employed graphic designer, earns $90,000 in net self-employment income in 2026. She pays $14,000 in health insurance premiums for herself and her family and $6,000 in unreimbursed medical expenses. What is her above-the-line deduction for health insurance?', '["$6,000", "$0", "$20,000", "$14,000"]'::jsonb, 3, 'Under Section 162(l), self-employed taxpayers may deduct 100% of health insurance premiums for themselves, their spouse, and dependents as an above-the-line deduction. Vasquez deducts $14,000 above the line. The $6,000 in unreimbursed medical expenses is deductible only on Schedule A to the extent it exceeds 7.5% of AGI under Section 213, not above the line. Choice C incorrectly combines both amounts as above-the-line deductions.', 'medium', 3),

-- Q27: medium / L2 — Educator expense deduction ($300 cap)
(3, 'Individual Taxation: Income', 'Morales, a full-time third-grade teacher at a public school, spends $450 on classroom supplies in 2026. She has no other above-the-line deductions and earns $52,000 in wages. What is Morales''s adjusted gross income?', '["$51,550", "$52,000", "$51,700", "$49,500"]'::jsonb, 2, 'Under Section 62(a)(2)(D), qualifying K-12 educators may deduct up to $300 of unreimbursed classroom expenses as an above-the-line deduction. Although Morales spent $450, the deduction is capped at $300. Her AGI = $52,000 minus $300 = $51,700. Choice A incorrectly deducts the full $450 spent. The educator expense deduction is available regardless of whether the teacher itemizes, making it valuable for teachers who take the standard deduction.', 'medium', 2),

-- Q28: medium / L2 — Casualty loss (federally declared disaster requirement)
(3, 'Individual Taxation: Income', 'Fleming''s home is damaged by a tornado in 2026 in an area that receives a federal disaster declaration. After insurance, the unreimbursed damage totals $25,000. Under current law, what is the threshold requirement for deducting this personal casualty loss?', '["The loss must exceed $500 per event", "The loss must exceed 2% of AGI", "The loss must result from a federally declared disaster", "The property must be used in a trade or business"]'::jsonb, 2, 'Under Section 165(h)(5), as modified by the TCJA, personal casualty losses are deductible only if attributable to a federally declared disaster. This eliminated deductions for routine theft, fire, or other personal casualties not tied to a federal declaration. Additionally, a $100 per-event floor and 10% of AGI threshold apply. Choice A states an incorrect floor amount ($500 vs the actual $100). The disaster declaration is the key gating condition under current law.', 'medium', 2),

-- Q29: hard / L4 — Material participation Test 4 (significant participation aggregation)
(3, 'Individual Taxation: Income', 'Park participates 180 hours in Activity X, 200 hours in Activity Y, and 150 hours in Activity Z during 2026. Each is a trade or business in which Park has an ownership interest and no other individual participates more. Park does not meet the 500-hour test for any single activity. Evaluate whether Park materially participates under the significant participation aggregation test.', '["Park does not materially participate because no single activity exceeds 500 hours", "Park materially participates in all three activities because aggregate significant participation hours exceed 500", "Park materially participates only in Activity Y because it has the most hours", "Park materially participates in X and Y only because Z has fewer than 200 hours"]'::jsonb, 1, 'Under Reg. 1.469-5T(a)(4), a significant participation activity is one in which the taxpayer participates more than 100 hours without meeting the 500-hour test individually. If aggregate hours across all SPAs exceed 500, the taxpayer materially participates in each. Park''s aggregate = 180 + 200 + 150 = 530 hours, exceeding 500. Choice A ignores the aggregation rule. Choice D imposes a nonexistent 200-hour minimum — the SPA threshold is only 100 hours.', 'hard', 4),

-- Q30: easy / L1 — MFS standard deduction amount
(3, 'Individual Taxation: Income', 'What is the approximate standard deduction for a taxpayer filing as married filing separately in 2026?', '["$7,500", "$15,000", "$30,000", "$22,500"]'::jsonb, 1, 'The standard deduction for Married Filing Separately is approximately $15,000 in 2026, which is half of the $30,000 MFJ amount. Choice C ($30,000) is the MFJ amount, available only when both spouses file jointly. Choice D ($22,500) is the Head of Household amount. MFS filers also face a reduced $5,000 SALT cap and other limitations, making this status generally less favorable than MFJ.', 'easy', 1)
;

COMMIT;
